window.SOSProfile=(()=>{
 const states='AC AL AP AM BA CE DF ES GO MA MT MS MG PA PB PR PE PI RJ RN RS RO RR SC SP SE TO'.split(' ');
 function mount(root){root.innerHTML=`<fieldset class="profile-fields"><legend>Dados pessoais</legend><div class="profile-grid"><label class="profile-wide">Nome completo<input name="fullName" autocomplete="name" required minlength="2" maxlength="150"><small>Seu nome completo aparecerá nas avaliações que você publicar.</small></label><label>CPF<input name="cpf" inputmode="numeric" placeholder="000.000.000-00" maxlength="14" required></label><label>Data de nascimento<input name="birthDate" type="date" autocomplete="bday" min="1900-01-01" max="${new Date().toISOString().slice(0,10)}" required></label><label>Gênero<select name="gender"><option value="not-informed">Prefiro não informar</option><option value="female">Feminino</option><option value="male">Masculino</option><option value="non-binary">Não binário</option><option value="other">Outro</option></select></label><label>Telefone com DDD<input name="phone" type="tel" autocomplete="tel-national" placeholder="(99) 99999-9999" maxlength="16" required></label></div></fieldset><fieldset class="profile-fields"><legend>Endereço</legend><div class="profile-grid"><label>CEP<input name="cep" inputmode="numeric" autocomplete="postal-code" placeholder="00000-000" maxlength="9" required></label><div class="cep-action"><button type="button" class="button outline" data-lookup-cep>Consultar CEP</button></div><p class="profile-wide cep-status" role="status" aria-live="polite">Ao consultar, apenas o CEP é enviado ao ViaCEP. Confira o endereço e informe o número.</p><label class="profile-wide">Rua / logradouro<input name="street" autocomplete="address-line1" maxlength="200" required></label><label>Número<input name="number" placeholder="Número ou S/N" maxlength="20" required></label><label>Complemento (opcional)<input name="complement" autocomplete="address-line2" placeholder="Apartamento, bloco…" maxlength="120"></label><label>Bairro<input name="neighborhood" maxlength="120" required></label><label>Cidade<input name="city" autocomplete="address-level2" maxlength="120" required></label><label>Estado<select name="state" autocomplete="address-level1" required><option value="">Selecione</option>${states.map(uf=>`<option value="${uf}">${uf}</option>`).join('')}</select></label></div></fieldset><p class="member-note">CPF, nascimento, gênero, telefone e endereço são dados privados do cadastro e não aparecem nas avaliações.</p>`;
 const input=name=>root.querySelector(`[name="${name}"]`),status=root.querySelector('.cep-status'),button=root.querySelector('[data-lookup-cep]');let controller,lastCep='',autofilled={};
 const digits=s=>s.replace(/\D/g,'');
 input('cpf').addEventListener('input',e=>{e.target.value=digits(e.target.value).slice(0,11).replace(/(\d{3})(\d)/,'$1.$2').replace(/(\d{3})(\d)/,'$1.$2').replace(/(\d{3})(\d{1,2})$/,'$1-$2')});
 input('phone').addEventListener('blur',e=>{const n=digits(e.target.value);e.target.value=n.replace(/^(\d{2})(\d{4,5})(\d{4})$/,'($1) $2-$3')});
 input('cep').addEventListener('input',e=>{const cep=digits(e.target.value).slice(0,8);e.target.value=cep.replace(/^(\d{5})(\d)/,'$1-$2');controller?.abort();button.disabled=false;if(lastCep&&cep!==lastCep){for(const[name,value]of Object.entries(autofilled))if(input(name).value===value)input(name).value='';autofilled={};lastCep='';status.textContent='Consulte o novo CEP ou preencha o endereço manualmente.'}});
 async function lookup(){const cep=digits(input('cep').value);if(cep.length!==8){status.textContent='Informe um CEP com 8 dígitos.';return}controller?.abort();const active=new AbortController();controller=active;const timer=setTimeout(()=>active.abort(),8000);button.disabled=true;status.textContent='Consultando CEP…';const before=Object.fromEntries(['street','neighborhood','city','state'].map(name=>[name,input(name).value]));
 try{const response=await fetch('https://viacep.com.br/ws/'+cep+'/json/',{signal:active.signal,credentials:'omit',referrerPolicy:'no-referrer'});if(!response.ok)throw Error();const data=await response.json();if(digits(input('cep').value)!==cep||controller!==active)return;if(data.erro){status.textContent='CEP não encontrado. Confira o número ou preencha o endereço manualmente.';return}const values={street:data.logradouro,neighborhood:data.bairro,city:data.localidade,state:data.uf};for(const[name,value]of Object.entries(values))if(typeof value==='string'&&input(name).value===before[name]){input(name).value=value;autofilled[name]=value}lastCep=cep;status.textContent='Endereço preenchido. Confira os dados, complete campos vazios e informe o número.'}
 catch{if(controller===active&&digits(input('cep').value)===cep)status.textContent='Não foi possível consultar o CEP. Você pode preencher o endereço manualmente.'}
 finally{clearTimeout(timer);if(controller===active)button.disabled=false}}
 button.onclick=lookup;input('cep').addEventListener('blur',()=>{if(digits(input('cep').value).length===8&&digits(input('cep').value)!==lastCep)lookup()});
 }
 function fill(root,profile){root.querySelectorAll('[name]').forEach(field=>{field.value=profile[field.name]|| (field.name==='gender'?'not-informed':'')})}
 return {mount,fill};
})();
